class Member:
    def __init__(self, name, monthly_fee):
        self.name, self.monthly_fee = name, monthly_fee
    def annual_fee(self): return self.monthly_fee * 12
class StudentMember(Member):
    def annual_fee(self): return super().annual_fee() * 0.5
def total_fees(members):
    return sum(member.annual_fee() for member in members)
